import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    result = list(range(1, n + 1))
    for i in range(k):
        result[i], result[i + 1] = result[i + 1], result[i]

    print(*(result))

if __name__ == "__main__":
    solve()
